SELECT Id,Name,NameEn,Sku,ShortDescription,FullDescription,Advantage,Disadvantage,MainCategoryId,MainManufacturerId,VendorId,Published,AllowCustomerReviews,Weight,Length,Width,Height,MetaTitle,MetaKeywords,MetaDescription,NoIndex,NoFollow,CreatedOnUtc,UpdatedOnUtc,Slug,PricingTypeId,GoldTypeId,GspWarrantyText FROM Product WHERE Id IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0))
